package br.com.onda;
import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class YouTubeFullscreenTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private YouTubeActivity activity;
 private Object field(String name)throws Exception{Field f=YouTubeActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{boolean[] ready={false};for(int i=0;i<300;i++){ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("YouTube fullscreen scenario timed out");}
 private void launch(){activity=(YouTubeActivity)ins.startActivitySync(new Intent(c,YouTubeActivity.class).putExtra(YouTubeFavorites.EXTRA,"https://m.youtube.com/watch?v=aqz-KE-bpKQ").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 @After public void after(){if(activity!=null){ins.runOnMainSync(activity::finish);ins.waitForIdleSync();}}
 private void report(String part,JSONObject value)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-fullscreen-"+part+".json"))){out.write(value.toString(2).getBytes("UTF-8"));}}
 @Test public void realHtmlVideoEntersFullscreenAndBackRestoresSameBrowser()throws Exception{launch();waitFor(()->field("web")!=null);WebView[] browser={null};int[] originalOrientation={0};ins.runOnMainSync(()->{try{browser[0]=(WebView)field("web");originalOrientation[0]=activity.getRequestedOrientation();WebViewClient delegate=browser[0].getWebViewClient();browser[0].stopLoading();browser[0].setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest request){try{if(request.getUrl().getPath().endsWith(".mp4"))return new WebResourceResponse("video/mp4",null,ins.getContext().getAssets().open("combined.mp4"));String html="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Onda fullscreen fixture</title></head><body style='margin:0'><button style='width:100%;height:80px' onclick=\"var v=document.querySelector('video');v.play();v.requestFullscreen();\">Assistir em tela cheia</button><video style='width:100%' playsinline controls loop src='https://m.youtube.com/onda-fullscreen.mp4'></video></body></html>";return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(html.getBytes("UTF-8")));}catch(Exception e){throw new RuntimeException(e);}}@Override public void onPageFinished(WebView w,String url){delegate.onPageFinished(w,url);}});browser[0].loadUrl("https://m.youtube.com/watch?v=aqz-KE-bpKQ");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->"Onda fullscreen fixture".equals(browser[0].getTitle()));int[] point=new int[2];ins.runOnMainSync(()->{browser[0].getLocationOnScreen(point);point[0]+=browser[0].getWidth()/2;point[1]+=Math.round(40*c.getResources().getDisplayMetrics().density);});long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,point[0],point[1],0),up=MotionEvent.obtain(now,now+80,MotionEvent.ACTION_UP,point[0],point[1],0);ins.getUiAutomation().injectInputEvent(down,true);ins.getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();waitFor(()->field("fullscreenView")!=null&&c.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE);ins.runOnMainSync(()->{try{assertSame(browser[0],field("web"));assertEquals(View.GONE,((View)field("page")).getVisibility());View full=(View)field("fullscreen");assertTrue(full.getWidth()>=activity.getWindow().getDecorView().getWidth()-2);assertTrue((activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_FULLSCREEN)!=0);assertTrue((activity.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_HIDE_NAVIGATION)!=0);}catch(Exception e){throw new RuntimeException(e);}});Bitmap shot=ins.getUiAutomation().takeScreenshot();if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-fullscreen.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);shot.recycle();}ins.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->field("fullscreenView")==null&&((View)field("page")).getVisibility()==View.VISIBLE);ins.runOnMainSync(()->{assertSame(browser[0],unchecked("web"));assertEquals(originalOrientation[0],activity.getRequestedOrientation());assertFalse(activity.isFinishing());});report("video",new JSONObject().put("realHtmlVideoRequest",true).put("realTouchGesture",true).put("landscapeWithoutBrowserRecreation",true).put("appControlsAndSystemBarsHidden",true).put("backRestoresSameBrowser",true));}
 private Object unchecked(String name){try{return field(name);}catch(Exception e){throw new RuntimeException(e);}}
 @Test public void duplicateRequestsAndLeavingScreenReleaseFullscreenExactlyOnce()throws Exception{launch();waitFor(()->field("web")!=null);AtomicInteger first=new AtomicInteger(),duplicate=new AtomicInteger();int[] flags={0},orientation={0},ui={0};ins.runOnMainSync(()->{try{WebView web=(WebView)field("web");web.stopLoading();flags[0]=activity.getWindow().getAttributes().flags;orientation[0]=activity.getRequestedOrientation();ui[0]=activity.getWindow().getDecorView().getSystemUiVisibility();WebChromeClient chrome=web.getWebChromeClient();chrome.onShowCustomView(new FrameLayout(activity),first::incrementAndGet);chrome.onShowCustomView(new FrameLayout(activity),duplicate::incrementAndGet);assertEquals(1,duplicate.get());assertEquals(0,first.get());Method pause=YouTubeActivity.class.getDeclaredMethod("onPause");pause.setAccessible(true);pause.invoke(activity);assertNull(field("fullscreenView"));assertEquals(1,first.get());chrome.onHideCustomView();assertEquals(1,first.get());assertEquals(orientation[0],activity.getRequestedOrientation());int mask=WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON;assertEquals(flags[0]&mask,activity.getWindow().getAttributes().flags&mask);assertEquals(ui[0],activity.getWindow().getDecorView().getSystemUiVisibility());Method resume=YouTubeActivity.class.getDeclaredMethod("onResume");resume.setAccessible(true);resume.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});report("lifecycle",new JSONObject().put("duplicateRequestDismissed",true).put("exitCallbackExactlyOnce",true).put("screenAwakeFlagRestored",true).put("orientationAndSystemUiRestored",true));}
}
